'use strict';(function(root){const art=new Image;art.src='rpg-fx/lich-ritual-atlas.png';function tile(p,frame,x,y,w,h){if(!art.complete||!art.naturalWidth)return false;const sw=art.naturalWidth/4,sh=art.naturalHeight/2;p.drawImage(art,frame%4*sw,Math.floor(frame/4)*sh,sw,sh,x-w/2,y-h/2,w,h);return true;}function vessel(p,x,y,time,scale=1){if(tile(p,0,x,y-24+Math.sin(time*3)*2,56*scale,56*scale))return;p.save();p.translate(x,y-20+Math.sin(time*3)*2);p.scale(scale,scale);p.fillStyle='#2e2346';p.fillRect(-12,-11,24,21);p.fillStyle='#9a849f';p.fillRect(-14,-14,28,5);p.fillRect(-14,8,28,5);p.fillStyle='#d9c99d';p.fillRect(-16,-10,4,18);p.fillRect(12,-10,4,18);p.fillStyle='#813fba';p.fillRect(-8,-8,16,13);p.fillStyle='#e4bcff';p.fillRect(-3,-6,6,9);for(let i=0;i<4;i++){const a=time*1.5+i*Math.PI/2;p.fillStyle=i%2?'#a971cf':'#e7d8ef';p.fillRect(Math.cos(a)*24-2,Math.sin(a)*8-4,4,4);}p.restore();}
function state(p,g,t){if(g.s.active!==11||g.h.cell!==5||!g.c.lich)return;const l=g.c.lich,c=g.c;if(l.vessel)vessel(p,l.vessel.x,l.vessel.y,t);for(const s of l.shots){p.save();p.translate(s.x,s.y);p.rotate(Math.atan2(s.vy,s.vx));p.fillStyle='#643293';p.fillRect(-25,-5,29,10);p.fillStyle='#c695e8';p.fillRect(-15,-3,20,6);p.fillStyle='#f7ebff';p.fillRect(-4,-2,12,4);p.restore();}for(let i=0;i<l.souls;i++){const a=t*.9+i*Math.PI/3;p.fillStyle='#d3b7ec';p.fillRect(c.x+Math.cos(a)*24-2,c.y-40+Math.sin(a)*9,4,6);}if(l.ward>0){p.save();p.strokeStyle='#af8bcf';p.lineWidth=3;for(let i=0;i<3;i++){p.beginPath();p.moveTo(c.x-24+i*18,c.y-7);p.lineTo(c.x-28+i*18,c.y-35);p.lineTo(c.x-18+i*18,c.y-49);p.stroke();}p.restore();}p.save();p.fillStyle='#dec7ef';p.font='bold 10px sans-serif';p.textAlign='center';p.fillText('영혼 '+l.souls+'/6',c.x,c.y-83);p.restore();}
function draw(p,f,t){if(f.heroId!==11||f.cell!==5)return false;if(t<0||t>1.5)return true;if(!f.phase){const o=f.from||f;p.save();p.globalAlpha*=Math.max(0,1-t/.65);p.fillStyle='#cfade9';for(let i=0;i<=f.slot;i++){p.fillRect(o.x-12+i*9,o.y-45-t*(15+f.slot*8),4,8+f.slot*3);}p.restore();return true;}const k=f.lichKind,x=f.x,y=f.y-20,o=f.from||f,q=Math.min(1,t/.7);p.save();p.globalAlpha*=Math.max(0,1-t/1.5);if(k==='vessel')vessel(p,x,y,t,1+Math.sin(q*Math.PI)*.5);else if(k==='soul'){p.fillStyle='#dfbaff';p.fillRect(o.x+(x-o.x)*q-3,o.y+(y-o.y)*q-3,6,8);}else if(k==='vessel-hit'){p.strokeStyle='#a573c7';p.lineWidth=2;p.beginPath();p.moveTo(o.x,o.y);p.quadraticCurveTo((x+o.x)/2,y-35,x,y);p.stroke();}else if(k==='ward'){for(let i=0;i<6;i++){const a=i*Math.PI/3;p.fillStyle='#b58ed0';p.fillRect(x+Math.cos(a)*(40-q*20)-3,y+Math.sin(a)*(40-q*20)-8,6,16);}}else if(k==='ritual'){if(tile(p,Math.min(3,1+Math.floor(t/.27)),x,y,220,160)){p.restore();return true;}const r=f.radius||180;p.fillStyle='#472555';p.globalAlpha*=.3;p.beginPath();p.ellipse(x,y+12,r*q,r*q*.5,0,0,Math.PI*2);p.fill();p.globalAlpha*=2;for(let i=0;i<8;i++){const a=i*Math.PI/4;p.fillStyle='#cab2dd';p.fillRect(x+Math.cos(a)*r*.65-3,y+Math.sin(a)*r*.33-12,6,24*(1-q)+5);}}else{if(k==='annihilation'&&tile(p,Math.min(7,4+Math.floor(t/.32)),x,y,(f.radius||180)*2,230)){p.restore();return true;}const n=k==='annihilation'?16:7,r=k==='annihilation'?(f.radius||180):40;for(let i=0;i<n;i++){const a=i*Math.PI*2/n;p.fillStyle=i%2?'#b17ed2':'#eee0f3';p.save();p.translate(x+Math.cos(a)*r*q,y+Math.sin(a)*r*q*.6);p.rotate(a+t);p.fillRect(-3,-15*(1-q),6,30*(1-q)+3);p.restore();}}p.restore();return true;}root.RPG_LICH_FX={draw,state};})(typeof window!=='undefined'?window:globalThis);
